#include "naval_repair_exact_phase.hpp"
#include "naval_repair_exact_detail.hpp"
#include "resident/kernel/command_types.hpp"
namespace hanmo::resident {using namespace naval_repair_exact_detail;namespace {
void current(const ExactNavalRepairReadContext& x,const WorldMoment& at){if(!same_moment(take(x.clock.read_current_moment()),at,x.budget))fail("ExactNavalRepairCurrentMomentRequired");}
void record_completion(ExactPhaseWriteContext& writes,const ExactNavalRepairReceipt& result){if(!result.completed||result.replayed)fail("ExactNavalRepairFreshCompletionRequired",result.action_id);ActionCompletion completion;completion.completed=true;completion.success=result.success;completion.code=result.reason;if(!writes.advance.completed_actions.insert(result.action_id,std::move(completion)))fail("DuplicateExactNavalRepairActionCompletion",result.action_id);}
}
Outcome<std::vector<ExactEventPrediction>> predict_exact_naval_repair_events(const CommonStore& c,const MilitaryState& m,const NavalState& n,const MilitaryActionTimeState& s,const ExactNavalRepairReadContext& x,const WorldMoment& now,const WorldMoment& upper){return guard<std::vector<ExactEventPrediction>>([&]{bound(c,m,n,s,x);current(x,now);take(make_moment_span(now,upper,x.budget));std::vector<ExactEventPrediction> out;for(const auto& row:s.naval_repair_time_sources.rows()){const auto& f=fact(s,row.first);validate_shape(c,m,n,s,x,f);if(f.original_result)continue;const auto completed=due(f,x.budget);if(take(compare_world_moments(completed,now,x.budget))<0)fail("ExactNavalRepairUnconsumedCompletion",row.first);if(take(compare_world_moments(completed,upper,x.budget))<=0)out.push_back({completed,ExactStage::action_completions,f.timing.start_fact_ref,2,0});}return out;});}
Status provide_exact_naval_repair_interval(CommonStore& c,const MilitaryState& m,const NavalState& n,MilitaryActionTimeState& s,ActionElapsedStore& elapsed,const ExactNavalRepairWriteContext& x,const MomentSpan& span){return status([&]{bound(c,m,n,s,x.read);current(x.read,span.to);for(const auto& row:s.naval_repair_time_sources.rows())if(!row.second.original_result)take(advance_exact_naval_repair_in_candidate(c,m,n,s,elapsed,x,row.first,span));});}
Outcome<ExactEventApplied> apply_exact_naval_repair_event(CommonStore& c,const MilitaryState& m,NavalState& n,MilitaryActionTimeState& s,ActionElapsedStore& elapsed,const ExactNavalRepairWriteContext& x,const ExactEventPrediction& p,ExactPhaseWriteContext& writes){return guard<ExactEventApplied>([&]{bound(c,m,n,s,x.read);current(x.read,p.at);if(p.stage!=ExactStage::action_completions||p.source_schema!=2||p.actual_source_basis.domain!="military_naval"||p.actual_source_basis.kind!="naval_repair_start"||p.dependency_revision)fail("ExactNavalRepairPredictionSourceMismatch",p.actual_source_basis.id);const auto& before=fact(s,p.actual_source_basis.id);if(before.original_result||!same_moment(due(before,x.read.budget),p.at,x.read.budget))fail("StaleExactNavalRepairPrediction",p.actual_source_basis.id);auto result=take(complete_exact_naval_repair_in_candidate(c,m,n,s,elapsed,x,p.actual_source_basis.id));if(!same_moment(result.occurred_at,p.at,x.read.budget))fail("ExactNavalRepairPredictionChangedWithoutResult",result.action_id);record_completion(writes,result);return ExactEventApplied{result.source_ref,2};});}
Status validate_exact_naval_repair_applied_source(const CommonStore& c,const MilitaryState& m,const NavalState& n,const MilitaryActionTimeState& s,const ActionElapsedStore& elapsed,const ExactNavalRepairReadContext& x,const ExactEventApplied& applied){return status([&]{take(read_verified_exact_naval_repair_result(c,m,n,s,elapsed,x,applied.applied_result,applied.source_schema));});}
Status consume_exact_naval_repair_interruptions(CommonStore& c,const MilitaryState& m,NavalState& n,MilitaryActionTimeState& s,ActionElapsedStore& elapsed,const ExactNavalRepairWriteContext& x,ExactPhaseWriteContext& writes){return status([&]{bound(c,m,n,s,x.read);for(const auto& row:s.naval_repair_time_sources.rows())if(!row.second.original_result){auto result=take(interrupt_exact_naval_repair_in_candidate(c,m,n,s,elapsed,x,row.first));if(result)record_completion(writes,*result);}});}
}
